// model/privacy.mjs -- notifications, URL redaction and the host settings file's container. One part of Model.mjs (D-REL-5); its import and export lines are generated by split-model.mjs on the dev branch.
import {
  QUOTE_OPEN, QUOTE_CLOSE, SEP, GLYPHS, NOTIFY_IDS
} from "./build.mjs"
import {
  str, asList, keyedMap, ownKeyValue
} from "./text.mjs"
import {
  cleanName
} from "./channels.mjs"
import {
  mergeConflictNotice, mergeDropNotice, stateUnreadableNotice
} from "./state.mjs"
import {
  parseHelperStatus, entryInputNotice
} from "./settings.mjs"
import {
  outputFailureSentence
} from "./player.mjs"
import {
  helperArgv
} from "./mpv.mjs"
import {
  formatCount, pluralChannels
} from "./epg.mjs"
import {
  CONTROL_RE, HOST_WITHHELD, runHostParts
} from "./sources.mjs"

// ---- D-SINK-18: the container the host settings file is, before a URL goes
// into it.
//
// `persistActive` writes the active source's playlist and EPG URLs onto the
// plugin's bar entry and the host persists that into
// ~/.config/omarchy/shell.json. The lead MEASURED (2026-10-09) that the
// packaged default of that file is 0644, that `omarchy-refresh-config`
// copies it with `cp -f` (so a first creation under the ordinary umask leaves
// it 0644), and that Quickshell's FileView with `atomicWrites: true` neither
// resets nor tightens the mode of a file that already exists: 0644 in, 0644
// out, content changed. So the plugin cannot assume the file it is putting a
// provider credential into is private -- while its OWN files are 0600 inside
// 0700 directories (rule 6).
//
// The owner's ruling: make that one file private BEFORE the URL goes in, and
// REFUSE to persist if it cannot be made private. QML cannot chmod, so the
// work is the helper's `config shield` verb; these three functions are the
// decision, lifted here so a test can call it (rule 12) instead of a QML
// component holding it where nothing can reach it.
//
// Deliberately NOT widened: nothing here looks at, reports or acts on the
// mode of ~/.config or ~/.config/omarchy. A 0600 file is sufficient whatever
// the directory modes are, and ~/.config is shared with everything on the
// system.
var CONFIG_SHIELD_UNKNOWN = ""
var CONFIG_SHIELD_PRIVATE = "private"
var CONFIG_SHIELD_EXPOSED = "exposed"
// D-SINK-18, found by the review: everything that was not exactly "private"
// collapsed to "exposed", so an ABSENT settings file refused every save
// permanently. There is no file, so there is no credential in it and nothing
// to tighten; the host creates it on the write and the re-arm that follows
// every write tightens it then. Refusing instead made the plugin
// unconfigurable on a machine that simply had no user config yet.
var CONFIG_SHIELD_ABSENT = "absent"

var CONFIG_PERSIST = "persist"
var CONFIG_REFUSE = "refuse"
var CONFIG_DEFER = "defer"

function configShieldArgv(helperPath) {
  return helperArgv(helperPath, ["config", "shield"])
}

// The verb's answer, collapsed to the only distinction the service acts on.
//
// FAIL CLOSED, and that is the whole shape of this function: `private` is
// returned only when the run said so three ways at once -- `ok`, `private`
// and the verdict string. Everything else is `exposed`: a crashed helper, no
// output at all, an unparseable line, one of the verb's other verdicts
// (absent, symlink, foreign, not_regular, replaced, error) and -- the case
// this is really written for -- a verdict string this version of the model has
// never heard of. A helper that learns a new verdict later cannot have it
// read as "private" by an older guide.
//
// There is no "unknown" return. Unknown means "the run has not answered
// yet", which is a fact about the SERVICE and not about the file, and
// conflating the two is how a broken helper would come to defer every write
// for ever.
function configShieldState(text) {
  var status = parseHelperStatus(text, "config")
  if (status.ok === true && status.private === true && str(status.verdict) === CONFIG_SHIELD_PRIVATE) {
    return CONFIG_SHIELD_PRIVATE
  }
  // An absent file is its own answer and not an exposure. Everything else --
  // a symlink, a device, someone else's file, a failed chmod, an unreadable
  // reply -- still fails CLOSED to "exposed", because each of those means we
  // could not establish that the file is private.
  if (str(status.verdict) === CONFIG_SHIELD_ABSENT) return CONFIG_SHIELD_ABSENT
  return CONFIG_SHIELD_EXPOSED
}

// Does this persist put a secret into the file?
//
// ANY non-empty URL does. Not "does it look like it has a password in it":
// a provider path token (`/live/USER/PASS/123.ts`) is a credential as surely
// as a query parameter is, which is why rule 5 treats whole URLs as secrets
// rather than trying to find the secret inside one.
//
// And the write that must NEVER be gated is the one that takes the URL OUT.
// `removeSource` persists ("", ""), and if that could be refused because the
// file is exposed then a user whose shell.json is 0644 could not remove the
// credential that is sitting in it -- the fix would hold the defect in place.
function persistCarriesSecret(playlistUrl, epgUrl) {
  return str(playlistUrl).trim() !== "" || str(epgUrl).trim() !== ""
}

// Three answers, because QML cannot block on a Process.
//
//   persist  the file is known private, or this write carries no secret
//   refuse   the file is known NOT private and could not be made private
//   defer    no answer yet -- hold the write, do not guess either way
//
// `defer` exists for one window: the shield runs at service start, and a
// persist that arrives before its first exit must neither write blind (which
// is the defect) nor fail the user (which would be a refusal we cannot
// justify, since the file may well be fine). After the first exit the state
// is always private or exposed, so this answer is reachable only in that
// window; see Service.qml's pendingPersist for what holding it means.
function configShieldDecision(state, playlistUrl, epgUrl) {
  if (!persistCarriesSecret(playlistUrl, epgUrl)) return CONFIG_PERSIST
  var s = str(state)
  if (s === CONFIG_SHIELD_PRIVATE) return CONFIG_PERSIST
  // No file means no credential in it. The host creates it on this write and
  // the re-arm after every write tightens it; the residual is that one gap,
  // which is stated in ARCHITECTURE and is smaller than refusing every save
  // on a machine that has no user config yet.
  if (s === CONFIG_SHIELD_ABSENT) return CONFIG_PERSIST
  if (s === CONFIG_SHIELD_EXPOSED) return CONFIG_REFUSE
  return CONFIG_DEFER
}

// D-SINK-19. The gate's question, asked of the ENTRY about to be written
// instead of of two argument names.
//
// Why this exists rather than a call that passes two empty strings. The
// plugin no longer writes a URL into the host's file at all -- `ownedEntryPatch`
// names `sourceKey` and `showLogos`, and `entryWith` strips the retired keys --
// so the gate above would never fire again on any shipping path, and a gate
// that cannot fire is a gate nobody notices breaking (rule 14). Asking the
// patch means the answer comes back REFUSE the moment a URL-bearing key is
// written again, whoever writes it and whatever they call it.
//
// IS A SOURCE KEY A SECRET? No, and this is the risk that decision accepts.
// A key is `fnv1a32` of the normalized playlist URL: eight hex characters,
// 32 bits, which cannot carry a URL back. What it can do is CONFIRM a guess
// -- anyone who can read `shell.json` may hash a candidate URL and see
// whether it matches -- so a reader who already holds a provider URL learns
// that this user has that account. That is a real loss, it is not zero, and
// it is smaller by a category than the credential itself, which is what used
// to be in the file. ACCEPTED, because the alternative is worse: gating the
// key write would let an exposed file refuse the very write that TAKES THE
// URL OUT, which is the trap `persistCarriesSecret` already documents one
// function above. The exposure is not "closed"; it is reduced from the
// credential to a 32-bit check on a guess.
function entryShieldDecision(state, patch) {
  var p = patch || {}
  return configShieldDecision(state, p.playlistUrl, p.epgUrl)
}

function seqArg(seq) {
  var n = Math.floor(Number(seq))
  return String(isFinite(n) && n > 0 ? n : 0)
}

// One `--mpv-arg=<token>` member per user token. The attached form is not
// cosmetic: argparse refuses an option-looking VALUE, so the separated form
// `--mpv-arg --profile=low-latency` dies with "expected one argument" - which
// is every realistic token, since mpv options all start with "--" (verified
// against python 3.14's argparse). Attached, each token is still exactly one
// argv member, never joined with another and never split.
function mpvArgArgv(mpvArgs) {
  var list = asList(mpvArgs)
  var out = []
  for (var i = 0; i < list.length; i++) {
    var token = str(list[i])
    if (token === "") continue
    out.push("--mpv-arg=" + token)
  }
  return out
}

function playerSessionArgv(socket, cacheDir, id, seq, scope, since, mpvArgs, ownerPid) {
  var argv = ["--socket", str(socket), "--cache-dir", str(cacheDir), "--id", str(id), "--seq", seqArg(seq)]
  if (str(scope) !== "") argv = argv.concat(["--scope", str(scope)])
  var when = Math.floor(Number(since))
  if (isFinite(when) && when > 0) argv = argv.concat(["--since", String(when)])
  var pid = Math.floor(Number(ownerPid))
  if (isFinite(pid) && pid > 0) argv = argv.concat(["--owner-pid", String(pid)])
  return argv.concat(mpvArgArgv(mpvArgs))
}

// `ownerPid` is optional and additive: passing Quickshell.processId here
// claims the player for this shell at the same moment it starts playing, so
// the plugin-removal case (PO-2 / PLAYER-LIVE-04) has a claim to check even
// when the service never ran a probe that found anything.
function playerStartArgv(socket, cacheDir, id, seq, scope, since, mpvArgs, ownerPid) {
  return ["player", "start"].concat(playerSessionArgv(socket, cacheDir, id, seq, scope, since, mpvArgs, ownerPid))
}

// `from` picks the first rung: "" or "quit" starts at `quit` over IPC,
// "term" skips straight to SIGTERM (the health verdict, where IPC is by
// definition not answering), "kill" to SIGKILL.
function playerStopArgv(socket, seq, from) {
  var argv = ["player", "stop", "--socket", str(socket), "--seq", seqArg(seq)]
  var rung = str(from)
  if (rung === "quit" || rung === "term" || rung === "kill") argv = argv.concat(["--from", rung])
  return argv
}

function playerRestartArgv(socket, cacheDir, id, seq, scope, since, mpvArgs, from, ownerPid) {
  var argv = ["player", "restart"].concat(playerSessionArgv(socket, cacheDir, id, seq, scope, since, mpvArgs, ownerPid))
  var rung = str(from)
  if (rung === "quit" || rung === "term" || rung === "kill") argv = argv.concat(["--from", rung])
  return argv
}

// PAUSE LIVE TV (2026-09-24). mpv keeps filling its cache while paused, so
// resuming continues from the moment it was pressed and the viewer is then
// behind live. Going back to BEFORE the keypress is `playerSeekArgv` (M5-01,
// 2026-10-03), which moves inside the same cache: an earlier version of this
// comment said "exactly ONE of 22 channels reported itself seekable, so
// there is no going back", a true reading of `seekable` with a false
// conclusion attached -- 31 of 32 channels rewound 20 s with that property
// reading false, because `demuxer-cache-state.seekable-ranges` is the one
// that decides (SPIKE-LIVE-REWIND.md, dev branch). The bound of a pause is mpv's
// 150 MiB forward quota: 315 s measured on a ~3.8 Mbps stream, less on a
// fatter one, with or without history behind it; a long pause then eats the
// rewind window one second per paused second (11.2).
//
// `state` is "on", "off" or "toggle"; anything else is a toggle, because a
// key that means "pause" must never be able to mean "start playing".
function playerPauseArgv(socket, state) {
  var want = str(state)
  if (want !== "on" && want !== "off") want = "toggle"
  return ["player", "pause", "--socket", str(socket), "--state", want]
}

// ------------------------------------------------------------ notifications

// argv for omarchy-notification-send per UX 6.4. Bodies never carry a URL.
// Options come first, then the constant headline, then the body. The
// wrapper (busctl-based) takes the body positionally unless it looks like
// one of its own flags (`--urgency=...`, `-g`, ...), so the body is built to
// never start with "-": the playlist-controlled name is quoted with the
// typographic quotes and cleaned of leading dashes (S-04).
//
// D-HOST-5 (owner, 2026-10-28). `replaceId` is the id the notification
// server returned for this kind's last card (Model.notifyPost keeps it): sent
// as `-r`, it replaces that card in place while the server still holds it,
// and an id the server no longer holds (the card expired or was dismissed)
// gets a fresh card -- both measured on Quickshell 0.3.1's server. With no
// such id the kind's fixed NOTIFY_IDS number goes out, which the server
// answers with a fresh card too. `-p` makes the wrapper print the id the
// server returned, which is how the next post of the kind finds it; it comes
// before `-r` so `-r <id> <headline>` stays one run of the argv.
//
// F-SINK-14 (2026-10-29). The channel name is redacted HERE, by sinkText,
// the one rule every place a provider's name is shown goes through: the
// guide's row printed `News HD (backup cdn.test)` while this body printed
// the whole credentialed URL, and the host keeps every body in its history.
// Redacted BEFORE cleanName, so the S-04 dash rule sees what is shown.
//
// D-SINK-49 (2026-10-29). The host renders the BODY as Text.StyledText
// (OMARCHY-PLUGIN-CONTRACT.md (dev branch), "Verified host renderers", and
// pinned by its host text-format test) behind a stripper that drops image tags
// only, and the Desktop Notifications spec leaves escaping to the client
// once a server advertises body-markup. So a `<b>`, a `<font>` or an
// `<a href>` in a provider's name or in a reason restyled this plugin's own
// card. The WHOLE body is escaped once, at the one exit below, so no branch
// -- and no branch added later -- can hand the renderer a tag; StyledText
// decodes the three entities, so the user reads the name exactly as the
// provider wrote it (an `&` included, which unescaped could swallow the
// text after it). The TITLE is not escaped: the host draws it PlainText
// (pinned the same way), where an entity would show as written.
//
// F-SINK-16 (2026-10-29). And the body carries no control character. The
// playlist parse keeps a provider's C0 and C1 controls in a name (measured:
// TAB, VT, FF, ESC, DEL, U+0085, U+009B, U+009D), the host turns a line
// break in a body into `<br/>`, and it persists every body as JSON under
// ~/.local/state/omarchy/notifications/, where JSON.stringify leaves DEL and
// C1 as they are for whatever prints the file. No body the plugin composes
// means anything by one. The name and the reason lose theirs BEFORE the
// redaction, as the player's title does (apply_channel): a TAB inside a
// password then no longer splits the URL there (D-SINK-34's cost) on this
// sink; and the whole body loses any left at the exit, before the escape.
function notifyArgv(event, params, replaceId) {
  var p = params || {}
  var spec = null
  var name = cleanName(sinkText(str(p.name).replace(CONTROL_RE, ""))) || "Channel"
  var reason = scrubUrls(str(p.reason).replace(CONTROL_RE, ""))
  if (event === "streamFailed") {
    spec = { title: "Stream failed", body: QUOTE_OPEN + name + QUOTE_CLOSE + " did not play" + (reason !== "" ? SEP + reason : ""), glyph: GLYPHS.tvOff, urgency: "normal", id: NOTIFY_IDS.streamFailed }
  } else if (event === "localPlayFailure") {
    // D-PLY-32: the same body as a stream failure -- the channel is what did
    // not play, the reason is why -- under a title that blames no stream,
    // because this machine refused before the stream was contacted
    // (Model.playerStartFailure "local"). The glyph is mpvMissing's, the
    // other local reason a player cannot start.
    spec = { title: "Could not start playback", body: QUOTE_OPEN + name + QUOTE_CLOSE + " did not play" + (reason !== "" ? SEP + reason : ""), glyph: GLYPHS.tvOff, urgency: "normal", id: NOTIFY_IDS.localPlayFailure }
  } else if (event === "playerStopped") {
    // D-PLY-33 (owner, 2026-10-28): the player died and mpv never said the
    // load failed (Model.deathReport). Nothing is known about the stream, so
    // the copy blames nothing, and the channel may have been playing for an
    // hour, so it does not say "did not play" (PO-4). A sentence and no
    // reason: what the log tail holds at a death with no end-file is a
    // driver warning as often as a cause (D-PLY-29), and a crash or a kill
    // leaves no line at all. The same S-04 quoting as every body with a name.
    spec = { title: "Playback stopped", body: QUOTE_OPEN + name + QUOTE_CLOSE + " stopped unexpectedly", glyph: GLYPHS.tvOff, urgency: "normal", id: NOTIFY_IDS.playerStopped }
  } else if (event === "outputFailed") {
    // D-PLY-37 (owner, 2026-10-28): mpv ended the load because an output of
    // THIS machine could not be opened (Model.deathReport card
    // "outputFailed"). The headline names the output, the body says the
    // channel stopped and why, in a sentence that blames this computer --
    // never "did not play", because the picture played until the stream
    // ended (measured: mpv 0.41.0 plays the video on and reports the audio
    // output only when the file ends). `output` is "audio" or "video"; the
    // sentence is Model.outputFailureSentence's, the one lastError records.
    var lost = p.output === "video" ? "video" : "audio"
    spec = { title: lost === "video" ? "Video output failed" : "Audio output failed",
             body: QUOTE_OPEN + name + QUOTE_CLOSE + " stopped" + SEP + outputFailureSentence(lost),
             glyph: GLYPHS.tvOff, urgency: "normal", id: NOTIFY_IDS.outputFailed }
  } else if (event === "playlistRefreshed") {
    spec = { title: "Playlist refreshed", body: pluralChannels(p.channelCount) + " in " + formatCount(p.groupCount) + (Number(p.groupCount) === 1 ? " group" : " groups"), glyph: GLYPHS.refresh, urgency: "low", id: NOTIFY_IDS.playlistRefreshed }
  } else if (event === "playlistError") {
    var tail = p.cachedAt ? "Using cached copy from " + str(p.cachedAt) + "." : "Open the guide for details."
    spec = { title: "Playlist error", body: "Could not fetch the playlist (" + (reason || "unknown error") + "). " + tail, glyph: GLYPHS.alert, urgency: "normal", id: NOTIFY_IDS.playlistError }
  } else if (event === "epgError") {
    spec = { title: "Guide data error", body: "Could not fetch the EPG (" + (reason || "unknown error") + "). Channels still work.", glyph: GLYPHS.alert, urgency: "low", id: NOTIFY_IDS.epgError }
  } else if (event === "mpvMissing") {
    spec = { title: "mpv not found", body: "Install mpv to play channels.", glyph: GLYPHS.tvOff, urgency: "critical", id: NOTIFY_IDS.mpvMissing }
  } else if (event === "entryInputRefused") {
    // R21b: the text is Model.entryInputNotice's and nothing else, so the
    // notification, the console line and the test read one sentence. It
    // takes a setting NAME and a reason, never a value (rule 5).
    var notice = entryInputNotice(p.setting, p.reason)
    spec = { title: notice.title, body: notice.body, glyph: GLYPHS.alert, urgency: "normal", id: NOTIFY_IDS.entryInputRefused }
  } else if (event === "stateUnreadable") {
    // R22a: Model.stateUnreadableNotice's sentence and nothing else, for the
    // same reason as the refusal above. A reason and a PATH, never a URL.
    // R27e: and the mid-session title when the block began after a load.
    var told = stateUnreadableNotice(p.reason, p.path, p.midSession === true)
    spec = { title: told.title, body: told.body, glyph: GLYPHS.alert, urgency: "critical", id: NOTIFY_IDS.stateUnreadable }
  } else if (event === "mergeDropped") {
    // R25b: Model.mergeDropNotice's sentence and nothing else -- counts and
    // caps, never a URL, a label, a query or a group name.
    var dropped = mergeDropNotice(p.dropped)
    if (dropped) spec = { title: dropped.title, body: dropped.body, glyph: GLYPHS.alert, urgency: "normal", id: NOTIFY_IDS.mergeDropped }
  } else if (event === "mergeConflict") {
    // D-SRC-33: Model.mergeConflictNotice's sentences and nothing else -- a
    // field name and a source key per conflict, never a value or a URL.
    var kept = mergeConflictNotice(p.conflicts)
    if (kept) spec = { title: kept.title, body: kept.body, glyph: GLYPHS.alert, urgency: "normal", id: NOTIFY_IDS.mergeConflict }
  }
  if (!spec) return null
  var held = notifyReplaceId(replaceId)
  return ["omarchy-notification-send", "--app-name", "IPTV", "-u", spec.urgency, "-g", spec.glyph, "-p",
          "-r", String(held > 0 ? held : spec.id), spec.title, markupEscape(str(spec.body).replace(CONTROL_RE, ""))]
}

// D-SINK-49: text on its way into a StyledText renderer, shown as written.
// `&` first, so the entities written for `<` and `>` are not escaped again.
// Quotes are left alone: with no `<` left there is no tag for an attribute
// to sit in, and StyledText draws a quote as a quote (measured, the QML
// spec's "D-SINK-49" case). Three single-character global replaces, linear.
function markupEscape(text) {
  return str(text).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
}

// ---- D-HOST-5 (owner, 2026-10-28): one card per notice kind, refreshed in place.
//
// The service posts every notice through ONE slot per kind (the notifyArgv
// event name). The slot holds the id the server returned for the kind's last
// card and sends it back as `-r` on the next post of that kind, so a repeated
// notice refreshes its card where the server still holds it. Two posts of a
// kind are never in flight together: the second would leave before the
// first's id came back and stack a second card. A post that arrives while
// its kind's post is in flight is HELD -- the latest replacing any earlier
// one held, because it would replace that card on screen anyway -- and goes
// out with the returned id when the post in flight answers. Kinds never wait
// on each other.
//
// The ids live in the service's memory only and are never saved. The server
// is the shell's own (Omarchy's notifications plugin runs in the same
// omarchy-shell process), and its ids start again from 1 with each server
// generation; memory that dies with the shell is the one store that can never
// hand a new generation an old id, which a saved id would -- and the server
// replaces whatever card holds an id, whichever program posted it.
//
// slots: a keyedMap of event -> { id, busy, held }, never mutated; every call
// returns a new map. `held` is the params of the post waiting, or null.

// A notice post (the wrapper, then busctl) normally answers in tens of
// milliseconds; this bounds one that does not, so a wedged post cannot hold
// its kind's later notices forever. busctl's own call timeout is 25 s.
var NOTIFY_POST_TIMEOUT_MS = 5000

// A server id as `-r` takes it: a positive integer in UINT32 range, else 0.
function notifyReplaceId(value) {
  var n = typeof value === "number" ? value : Number(str(value))
  if (!isFinite(n) || n !== Math.floor(n) || n < 1 || n > 4294967295) return 0
  return n
}

// The id `omarchy-notification-send -p` printed: one decimal integer on one
// line. Anything else -- a wrapper that failed (it exits non-zero and prints
// nothing), a logging stub that prints nothing, a post the watchdog ended, a
// crash -- is 0, "no id held": the next post of the kind goes out with the
// fixed number and gets a fresh card, the safe direction.
function notifyReplyId(text, exitCode) {
  if (Number(exitCode) !== 0) return 0
  var m = /^[ \t]*([0-9]{1,10})[ \t]*\r?\n?$/.exec(str(text))
  return m ? notifyReplaceId(Number(m[1])) : 0
}

function notifySlot(slots, event) {
  var s = slots && typeof slots === "object" ? ownKeyValue(slots, str(event)) : null
  return {
    id: s ? notifyReplaceId(s.id) : 0,
    busy: !!(s && s.busy === true),
    held: s && s.held !== undefined && s.held !== null ? s.held : null
  }
}

function withNotifySlot(slots, event, slot) {
  var out = keyedMap()
  var keys = slots && typeof slots === "object" ? Object.keys(slots) : []
  for (var i = 0; i < keys.length; i++) out[keys[i]] = slots[keys[i]]
  out[str(event)] = slot
  return out
}

// A notice to post. Returns { slots, argv }: argv is the command to run now,
// or null when the kind's post is in flight (the notice is held) or the event
// makes no card (notifyArgv's null: an unknown event, a merge with nothing
// dropped).
function notifyPost(slots, event, params) {
  if (notifyArgv(event, params) === null) return { slots: slots, argv: null }
  var slot = notifySlot(slots, event)
  var p = params || {}
  if (slot.busy) return { slots: withNotifySlot(slots, event, { id: slot.id, busy: true, held: p }), argv: null }
  return { slots: withNotifySlot(slots, event, { id: slot.id, busy: true, held: null }), argv: notifyArgv(event, p, slot.id) }
}

// A post of `event` answered: its stdout and exit code. The slot now holds
// what this post returned -- the id of the card it made or refreshed, or none
// -- and a notice held meanwhile goes out at once with that id. Returns
// { slots, argv } as notifyPost does.
function notifyAnswered(slots, event, text, exitCode) {
  var slot = notifySlot(slots, event)
  var id = notifyReplyId(text, exitCode)
  if (slot.held !== null) {
    var argv = notifyArgv(event, slot.held, id)
    if (argv !== null) return { slots: withNotifySlot(slots, event, { id: id, busy: true, held: null }), argv: argv }
  }
  return { slots: withNotifySlot(slots, event, { id: id, busy: false, held: null }), argv: null }
}

// ------------------------------------------------------------ privacy

// "scheme://host" for http(s) URLs, "local file" for paths, "" otherwise.
// Never returns path, query or userinfo (credentials live there).
//
// D-SINK-23. The userinfo is searched for INSIDE THE AUTHORITY, which ends at
// the first `/`, `?` or `#` (RFC 3986), and not at the first `/` alone. On a
// URL with no path the old `(?:[^\/\s]*@)?` crossed into the query, took an
// at-sign THERE as the end of the userinfo, and printed what followed it as
// the host: `http://h.test?u=me@b.test&p=SECRET` gave `b.test&p=SECRET`,
// while the helper's url_host (urllib) gave `h.test`. A bracketed IPv6 host
// is kept whole (it used to stop at its first `:` and read as `[`).
// R32a (D-SINK-27): this is a DISPLAY sink and shows the RFC host, the one
// validateSourceUrl and the helper's urllib read; the round-2 reading that
// showed the host after a later at-sign is withdrawn. The free-text
// redactor below reads differently, on purpose, and says why.
function sourceLabel(url) {
  var text = str(url).trim()
  if (text === "") return ""
  if (/^file:/i.test(text)) return "local file"
  // D-SINK-1's authority rule, which this spelling did not get when
  // redactUrls got it: userinfo runs to the LAST `@` of the authority
  // (RFC 3986) and the host group excludes `@` entirely. With the old
  // `(?:[^@\/\s]*@)?([^\/\s?#:]+)` pair, `http://user:p@ss@host/x` labelled
  // itself `http://ss@host` -- the password TAIL in the host position, which
  // is the defect redactUrls was fixed for. Both halves are needed: either
  // alone still leaks. M4-01 made this reachable from a remote party, because
  // resolveEpgUrl publishes `hostOf` over a `url-tvg` the PLAYLIST declared.
  // D-SINK-30: the host group ends at `;`, `=` and `&` too, as runHostParts
  // cuts the free-text host (reg-name admits them; no real host carries
  // them), so `http://h.test;sid=SECRET/x` labels as `http://h.test`.
  //
  // F-SINK-15 (2026-10-29). The AUTHORITY is hostPortOf's -- everything up
  // to the first `/`, `?` or `#`, its userinfo cut at the LAST `@` -- and not
  // a pattern of its own. The userinfo group here used to stop at JS
  // whitespace as well, so on text with a space or U+3000 in the password the
  // optional group failed and the host group took the USERNAME:
  // `http://user:pa ss@cdn.test/x` labelled itself `http://user` where
  // hostPortOf, the helper's urllib and validateSourceUrl all read
  // `cdn.test`. Latent (every caller passes a validated URL, and validation
  // refuses whitespace), and the third printer with a boundary of its own.
  // The HOST still ends at whitespace, so nothing after one is printed.
  var m = text.match(/^([a-z][a-z0-9+.-]*):\/\/([^\/?#]*)/i)
  if (m) {
    var scheme = m[1].toLowerCase()
    if (scheme === "file") return "local file"
    var hostport = m[2].substring(m[2].lastIndexOf("@") + 1)
    var h = hostport.match(/^(?:\[[^\/?#\s\]]*\]|[^\/\s?#:@\[;=&]+)/)
    if (h) return scheme + "://" + h[0]
  }
  if (text.charAt(0) === "/" || text.charAt(0) === "~") return "local file"
  return "unknown source"
}

function hostOf(url) {
  var label = sourceLabel(url)
  var at = label.indexOf("://")
  return at === -1 ? label : label.substring(at + 3)
}

// Replace every `scheme://...` in free text by its host alone (R12, D-QA-01):
// userinfo, port, path and query are gone. Applied at every sink that can
// carry mpv or helper output (notifications, lastError, console, tooltips).
// D-SINK-1. The userinfo group used to be `(?:[^@\/\s]*@)?`, which cannot span
// a SECOND `@` -- while the host group happily accepted one. A provider whose
// password contains an un-encoded `@` therefore had its password TAIL survive
// into the host position and out through a desktop notification. RFC 3986 puts
// userinfo before the LAST `@` of the authority, so the group now runs to it
// and the host excludes `@` entirely. Both changes are needed: either alone
// still leaks.
//
// F-SINK-11. The scan is ANCHORED ON "://" and never re-reads a run of
// scheme-legal characters, so the cost is linear in the length of the text.
//
// What was wrong. The pattern was
// `/[a-z][a-z0-9+.-]*:\/\/(?:[^\/\s]*@)?([^\/\s?#:@]*)[^\s]*/gi`. On a run of
// scheme-legal characters the engine consumed the whole run from EVERY start
// position and backtracked out of it, so the cost was quadratic. Measured on
// node v26.8.1 over a run of letters: 2.5 ms at 1,000 characters, 40.1 at
// 5,000, 159.0 at 10,000, 659.3 at 20,000, 2578.5 at 40,000. After this
// change, same vector and same machine: 0.001 ms at every one of those five
// sizes. The guarded entry point `sinkText` does NOT cover the case that
// matters: a long run in the same string as a URL still contains "://", so it
// still paid the whole cost -- "http://u:p@h.test/x " followed by 40,000
// letters cost 2575.8 ms through this function and 0.001 ms after this change.
// The slowest vector that remains is a run of letters ending in a real URL,
// where the whole run is the "scheme" the old pattern also swallowed: 0.050 /
// 0.034 / 0.049 / 0.094 / 0.195 ms over the same five sizes. IT IS ALSO THE
// ONE VECTOR THIS CHANGE MAKES SLOWER, and saying so is the point: the old
// pattern consumed that run in the engine and this walks it in JS, 0.058 ms
// against 0.191 at 40,000 characters and 1.5 ms against 8.6 at 1 MiB. Linear
// either way. The trade is three orders of magnitude on the shapes that were
// quadratic for a factor of five on the one that never was.
//
// Why it is the same answer, rather than a narrower pattern. The old pattern
// could only match where a `://` follows a run of scheme-legal characters
// beginning with a letter, and `:` and `/` are not scheme-legal, so the greedy
// run always ended EXACTLY at that `://`: there was never a shorter candidate
// to backtrack to. So "walk back from each `://` over the scheme-legal run,
// then forward to the first letter in it" picks the same leftmost start the
// engine picked, and the host rule below was the old groups transcribed
// character class by character class -- until R32a moved what the rule SAYS
// (the paragraph on the scan itself, below). The node suite (dev branch)
// drives a pattern that states the R32a rule as an oracle over the shared
// fixture and thousands of generated strings and asserts the two agree
// character for character, so the claim is checked rather than argued.
//
// This makes the caps that currently stand in front of every sink CHEAP, not
// unnecessary. The caps are still the reason a 64 MiB description cannot
// reach a renderer at all; this only stops redaction itself being the thing
// that stalls when one does.
var SPACE_RE = /\s/

// `\s` exactly as the old pattern's `[^\s]` and `[^\/\s]` read it: the ASCII
// cases without a regex call, everything above it by asking the engine, so
// U+00A0, the Zs block, U+2028/9 and U+FEFF are not quietly reclassified.
function isSpaceAt(s, i) {
  var c = s.charCodeAt(i)
  if (c === 32 || (c >= 9 && c <= 13)) return true
  if (c < 128) return false
  return SPACE_RE.test(s.charAt(i))
}

// TWO whitespace classes for two purposes, and the difference is the rule
// (R32a''', 2026-10-22, D-SINK-36; R32a'' before it, D-SINK-32, D-SINK-33):
//
//   A URL READER REFUSES THE UNION. validateSourceUrl (and the helper's
//   validate_source_url over URL_SPACE_CHARS) refuses a typed or stored URL
//   holding ANY member of URL_SPACE_CODES, the union of JS `\s`, Python
//   `\s` and U+FEFF, so that no engine's own notion of whitespace is ever
//   consulted and a URL one mirror accepts is never one the other splits.
//
//   A FREE-TEXT REDACTOR DELIMITS AT ASCII. redactUrls ends a URL run, and
//   runHostParts ends its authority, at URL_DELIMITER_CODES ONLY: space,
//   tab, LF, CR, FF, VT -- six code points, the helper's URL_DELIMITER_CHARS
//   the same six. Every other whitespace or control code point is URL TEXT:
//   a password holding U+FEFF, NBSP, U+2028, U+0085 or an information
//   separator stays inside the run, its authority ends at the `@`, and the
//   HOST prints. Under R32a'' both redactors ended the run at the union, and
//   each mirror took the other's worse case: the helper printed
//   `http://myuser<U+FEFF>ss@prov.test/live/1.ts` -- the username and the
//   tail -- where 0.14.3 printed the host (D-SINK-36). A redactor's job is
//   that nothing of a credential survives; the wider the class that ends
//   the run, the more of a password it copies through. The accepted cost
//   (D-SINK-34) is now confined to the six delimiters: a SPACE or a TAB
//   inside a password still splits the run, and the shared fixture pins
//   that output for each of the six and the HOST for every other member.
//
// Both lists are pinned code point by code point over the whole Unicode
// range by the shared url-whitespace fixture (dev branch) in both suites.
// The union, every member listed:
//   U+0009 tab, U+000A LF, U+000B VT, U+000C FF, U+000D CR,
//   U+001C U+001D U+001E U+001F (the information separators: Python's `\s`,
//     not JS's),
//   U+0020 space, U+0085 NEL (Python's, not JS's), U+00A0 NBSP,
//   U+1680 ogham space, U+2000..U+200A (en quad .. hair space),
//   U+2028 line separator, U+2029 paragraph separator,
//   U+202F narrow NBSP, U+205F medium mathematical space,
//   U+3000 ideographic space, U+FEFF (JS's `\s`, not Python's).
// `'`, `"`, `<` and `>` are in neither: they ended the helper's run until
// R32a'' (D-SINK-33, a password holding `'` printed the username and the
// tail) and are trailing punctuation now, stripped off the run's end and
// put back (redactUrls). isSpaceAt above stays JS `\s` for trimEndSpace.
var URL_SPACE_CODES = [0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x85, 0xa0,
  0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007, 0x2008, 0x2009,
  0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000, 0xfeff]

// The reader's class: what validateSourceUrl refuses.
function isUrlSpaceAt(s, i) {
  var c = s.charCodeAt(i)
  if (c === 0x20 || (c >= 0x09 && c <= 0x0d) || (c >= 0x1c && c <= 0x1f)) return true
  if (c < 0x85) return false
  return c === 0x85 || c === 0xa0 || c === 0x1680 || (c >= 0x2000 && c <= 0x200a)
    || c === 0x2028 || c === 0x2029 || c === 0x202f || c === 0x205f || c === 0x3000 || c === 0xfeff
}

// The index of the first member of the reader's class in `s`, or -1
// (validateSourceUrl): one index walk, nothing retried.
function urlSpaceIndex(s) {
  for (var i = 0; i < s.length; i++) if (isUrlSpaceAt(s, i)) return i
  return -1
}

// The redactor's class (R32a'''): the six ASCII delimiters, and nothing
// else, end a free-text URL run (redactUrls) and its authority
// (runHostParts). Mirrors the helper's URL_DELIMITER_CHARS.
var URL_DELIMITER_CODES = [0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20]

function isUrlDelimiterAt(s, i) {
  var c = s.charCodeAt(i)
  return c === 0x20 || (c >= 0x09 && c <= 0x0d)
}

// The index of the first delimiter in `s`, or -1 (runHostParts): one index
// walk, nothing retried.
function urlDelimiterIndex(s) {
  for (var i = 0; i < s.length; i++) if (isUrlDelimiterAt(s, i)) return i
  return -1
}

// R32a''. The sentence punctuation a free-text redactor strips off the end
// of a URL run and puts back after the host, both mirrors alike (the
// helper's redact_urls has the same set): the helper always restored
// `.,;:!?)]`, the model never did, and `'"<>` ended the helper's run
// (D-SINK-33). A `]` is kept when the run holds a `[`: it closes an IPv6
// literal. Returns the number of characters to put back.
function trailingPunctuationLength(run) {
  var bracket = run.indexOf("[") !== -1
  var k = run.length
  while (k > 0) {
    var ch = run.charAt(k - 1)
    if (".,;:!?)]'\"<>".indexOf(ch) === -1 || (bracket && ch === "]")) break
    k--
  }
  return run.length - k
}

// `[a-z0-9+.-]` under the `i` flag.
function isSchemeRestCode(c) {
  return (c >= 97 && c <= 122) || (c >= 65 && c <= 90) || (c >= 48 && c <= 57)
    || c === 43 || c === 46 || c === 45
}

// `[a-z]` under the `i` flag: the first character of a scheme.
function isLetterCode(c) {
  return (c >= 97 && c <= 122) || (c >= 65 && c <= 90)
}

function redactUrls(text) {
  var s = str(text)
  var j = s.indexOf("://")
  if (j === -1) return s               // the old pattern cannot match: same answer
  var n = s.length
  var out = ""
  var copied = 0                       // everything before this is already in `out`
  // The engine's lastIndex: no match may start before it. `j` is only ever
  // searched from `resume` or from a position already at or past it, so there
  // is no `j < resume` case to guard -- and a guard for a case that cannot
  // happen is a branch no test can go red for.
  var resume = 0
  while (j !== -1) {
    // The leftmost start the old pattern would have taken for this "://":
    // back over the scheme-legal run, then forward to its first letter.
    var b = j
    while (b > resume && isSchemeRestCode(s.charCodeAt(b - 1))) b--
    var p = b
    while (p < j && !isLetterCode(s.charCodeAt(p))) p++
    if (p >= j) {
      // No letter in the run, so the pattern has no match ending here.
      // j+1 and j+2 cannot begin a "://" of their own; +1 keeps that from
      // being load-bearing.
      j = s.indexOf("://", j + 1)
      continue
    }
    // The run: to the first ASCII delimiter (R32a''', isUrlDelimiterAt: the
    // six; it was the old `[^\s]*` tail, JS `\s`, until 2026-10-22, and the
    // 30-point union for one round after that), then the sentence
    // punctuation stripped off its end and put back after the host, so
    // `... http://h.test/x.` prints `h.test.` as the helper does.
    var end = j + 3
    while (end < n && !isUrlDelimiterAt(s, end)) end++
    var put = trailingPunctuationLength(s.substring(j + 3, end))
    var runEnd = end - put
    // R32a' (D-SINK-29, 2026-10-22; D-SINK-23, D-SINK-28). This is a
    // FREE-TEXT redactor, not a parser: the string is an mpv error, a helper
    // line, a notification body, and the one job here is that NOTHING of a
    // credential survives, with the host as a courtesy. The host is the RFC
    // one -- the authority ends at the first `/`, `?`, `#` or whitespace, its
    // userinfo at the LAST `@` WITHIN it (D-SINK-1), and the printed host is
    // cut at the first `:`, `;`, `=` or `&` so a neighbouring parameter never
    // prints (D-SINK-23: `http://h.test?u=me@b.test&p=SECRET` -> `h.test`) --
    // and it is WITHHELD, as the one token `[host withheld]`, when that host
    // has no dot and an `@` follows the authority: a dotless "host" with a
    // later `@` is most likely a username in front of a password holding an
    // unencoded `/`, `?` or `#`, and printing it printed the username
    // (`http://myuser:pa#ss@cdn.test/x` -> `myuser`, D-SINK-28). Two
    // readings were tried and withdrawn, and both are kept here as the
    // reason this one is not "tidied" back:
    //   - the authority ended at the first `/` alone (the pattern F-SINK-11
    //     transcribed, 0.14.3): on a URL with no path the at-sign search ran
    //     on into the query and printed `b.test&p=SECRET`, the password with
    //     it (D-SINK-23).
    //   - the userinfo run to the LAST `@` of the whole run, crossing `/`
    //     (round 3, lane-bounds-s2, never shipped): an `@` INSIDE a path or
    //     query credential moved the printed "host" onto the credential, so
    //     `http://prov.test/live/U5ER/P4@SSW0RD/1.ts` printed `SSW0RD` -- a
    //     password tail, on mpv's error line into the journal and the
    //     notification (D-SINK-29). The RFC authority never crosses a `/`.
    // The cost, stated (ARCHITECTURE-SOURCES 3.1): a dotless intranet URL
    // with a path `@` (`http://nas:8000/files/me@home/x`) withholds `nas`;
    // `localhost` gets no exemption. The predicate is Model.urlHostWithheld,
    // the same one the Sources form warns with, and the helper's
    // redact_urls (run_host) is the same rule; the shared fixture holds both
    // to it. runHostParts is one pass over the run.
    // R32a'' (2026-10-22, D-SINK-32, D-SINK-33): `'"<>` never end a run (a
    // password may hold them) and are trailing punctuation instead; and
    // the predicate has a second arm, a NON-NUMERIC port followed by a
    // later `@` (`http://user.name:pa/ss@h.test/x` is a dotted username and
    // a password, withheld; D-SINK-35). R32a''' (D-SINK-36): the run and
    // the authority end at the six ASCII delimiters (isUrlDelimiterAt) in
    // both mirrors and at NOTHING else, so a password holding U+FEFF, NBSP,
    // U+2028, U+0085 or U+001C..U+001F redacts to the host. The cost that
    // remains, accepted as D-SINK-34 and confined to the six: a space or a
    // tab INSIDE a password splits the run, so `http://myuser:pa ss@cdn.test/x`
    // prints `myuser ss@cdn.test/x` -- the fixture pins that output for
    // each delimiter and the host for every other whitespace code point.
    var parts = runHostParts(s.substring(j + 3, runEnd))
    var host = parts.withheld ? HOST_WITHHELD : parts.host
    out += s.substring(copied, p) + (host !== "" ? host : "[url]") + s.substring(runEnd, end)
    copied = end
    resume = end
    j = s.indexOf("://", resume)
  }
  return out + s.substring(copied)
}

// Older name kept for callers; same behaviour.
function scrubUrls(text) {
  return redactUrls(text)
}

// F-SINK-10. Provider-controlled text on its way to a guide-text or
// accessibility sink, redacted exactly as redactUrls redacts it and at a
// linear cost.
//
// WHY THIS EXISTS AS ITS OWN NAME rather than `redactUrls` at each call site.
// It was written because redactUrls was QUADRATIC in a run of scheme-legal
// characters, and these sinks run per instantiated row, on every clock tick
// and on every keystroke in search mode -- the one place in this plugin where
// a 0.6 ms call is not free. F-SINK-11 removed that reason: redactUrls is
// linear now and takes this very exit itself, so what is left here is one
// `indexOf` instead of one call, and the NAME, which is the part that was
// always load-bearing -- it is how the four composers below cannot drift
// about where redaction happens. The exit is EXACT and not an approximation:
// redactUrls cannot rewrite text with no "://" in it, and the node suite
// asserts the two agree over every input it is given.
//
// WHY AT THE SINK and not at one caller. The strings these sinks compose come
// from an XMLTV programme title and an M3U channel name, both written by the
// provider. Until M4-01 the matcher matched 0 of 1,453 channels on the
// owner's install, so the row's now/next title was empty on every row and the
// gap was theoretical; M4-01 made it 227 channels of provider-written titles.
// Redacting in the composers (rowDetail, rowAccessibleName, formatEpgLine)
// AND at the epgFields boundary that feeds them means a caller that hands a
// raw title in is still safe, which a fix at one caller does not give.
function sinkText(value) {
  var s = str(value)
  return s.indexOf("://") === -1 ? s : redactUrls(s)
}
export {
  CONFIG_SHIELD_UNKNOWN, CONFIG_SHIELD_PRIVATE, CONFIG_SHIELD_EXPOSED,
  CONFIG_SHIELD_ABSENT, CONFIG_PERSIST, CONFIG_REFUSE, CONFIG_DEFER,
  configShieldArgv, configShieldState, persistCarriesSecret,
  configShieldDecision, entryShieldDecision, seqArg, mpvArgArgv,
  playerSessionArgv, playerStartArgv, playerStopArgv, playerRestartArgv,
  playerPauseArgv, notifyArgv, markupEscape, NOTIFY_POST_TIMEOUT_MS,
  notifyReplaceId, notifyReplyId, notifySlot, withNotifySlot, notifyPost,
  notifyAnswered, sourceLabel, hostOf, SPACE_RE, isSpaceAt, URL_SPACE_CODES,
  isUrlSpaceAt, urlSpaceIndex, URL_DELIMITER_CODES, isUrlDelimiterAt,
  urlDelimiterIndex, trailingPunctuationLength, isSchemeRestCode,
  isLetterCode, redactUrls, scrubUrls, sinkText
}
